sys_script_include.script:
var OfficeBaseValidation = Class.create();
OfficeBaseValidation.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    checkDuplicates: function() {
        var baseSysId = this.getParameter('sysparm_sys_id'); 
        var name = this.getParameter('sysparm_name');
        var city = this.getParameter('sysparm_city');
        var state = this.getParameter('sysparm_state');

        var grName = new GlideRecord('x_1834930_office_0_office_base');
        grName.addQuery('name', name);
        if (baseSysId) grName.addQuery('sys_id', '!=', baseSysId);
        grName.query();
        if (grName.hasNext()) return 'duplicate_name';

        var grCityState = new GlideRecord('x_1834930_office_0_office_base');
        grCityState.addQuery('city', city);
        grCityState.addQuery('state', state);
        if (baseSysId) grCityState.addQuery('sys_id', '!=', baseSysId);
        grCityState.query();
        if (grCityState.hasNext()) return 'duplicate_city_state';

        return 'ok';
    }

});
